def _load_model():
    if _EMBEDDED_MODEL_B64:
        raw = zlib.decompress(base64.b64decode(_EMBEDDED_MODEL_B64.encode("ascii")))
        return json.loads(raw.decode("utf-8"))
    raise ValueError("embedded model is empty")


def _tree_probability(model, values):
    raw = float(model["baseline"])
    for tree in model["fast_trees"]:
        feature, threshold, missing, left, right, leaf, value = tree
        i = 0
        while not leaf[i]:
            x = values[feature[i]]
            go_left = missing[i] if np.isnan(x) else x <= threshold[i]
            i = left[i] if go_left else right[i]
        raw += value[i]
    if raw >= 0:
        z = math.exp(-raw)
        return 1.0 / (1.0 + z)
    z = math.exp(raw)
    return z / (1.0 + z)


def _batch_probabilities(model, rows):
    """Score the whole daily universe tree-by-tree instead of stock-by-stock."""
    x = np.asarray(rows, dtype=float)
    raw = np.full(len(x), float(model["baseline"]), dtype=float)
    for feature, threshold, missing, left, right, leaf, value in model["fast_trees"]:
        nodes = np.zeros(len(x), dtype=np.int32)
        active = ~leaf[nodes]
        while np.any(active):
            ri = np.flatnonzero(active); ni = nodes[ri]; fi = feature[ni]
            xv = x[ri, fi]
            go_left = np.where(np.isnan(xv), missing[ni], xv <= threshold[ni])
            nodes[ri] = np.where(go_left, left[ni], right[ni])
            active[ri] = ~leaf[nodes[ri]]
        raw += value[nodes]
    out = np.empty_like(raw); positive = raw >= 0
    out[positive] = 1.0 / (1.0 + np.exp(-raw[positive]))
    z = np.exp(raw[~positive]); out[~positive] = z / (1.0 + z)
    return out


def _last_features(df):
    if df is None or len(df) < 120:
        return None
    x = df.sort_index()
    c = x["close"].to_numpy(dtype=float); v = x["volume"].to_numpy(dtype=float)
    high = x["high"].to_numpy(dtype=float); low = x["low"].to_numpy(dtype=float)
    r = c[1:] / c[:-1] - 1.0
    vchg = v[1:] / v[:-1] - 1.0
    out = {}
    out["ret5"], out["ret20"], out["ret60"] = c[-1] / c[-6] - 1, c[-1] / c[-21] - 1, c[-1] / c[-61] - 1
    out["range20"] = np.max(high[-20:]) / np.min(low[-20:]) - 1
    out["range60"] = np.max(high[-60:]) / np.min(low[-60:]) - 1
    out["dd20"] = c[-1] / np.max(c[-20:]) - 1
    out["vol20"], out["vol60"] = np.std(r[-20:], ddof=1), np.std(r[-60:], ddof=1)
    mean_v20 = np.mean(v[-20:])
    out["volume_ratio"] = np.mean(v[-5:]) / mean_v20
    out["volume_cv"] = np.std(v[-20:], ddof=1) / mean_v20
    out["up_volume_share"] = np.sum(v[-20:][r[-20:] > 0]) / np.sum(v[-20:])
    out["pv_corr"] = np.corrcoef(r[-20:], vchg[-20:])[0, 1]
    low60, high60 = np.min(c[-60:]), np.max(c[-60:])
    out["close_pos60"] = (c[-1] - low60) / (high60 - low60) if high60 != low60 else np.nan
    out["turn20"] = np.mean(x["turnover_rate"].to_numpy(dtype=float)[-20:])
    amount20 = np.mean(x["turnover"].to_numpy(dtype=float)[-20:])
    out["amount20"] = np.log1p(amount20)
    out["breakout_gap"] = c[-1] / np.max(c[-61:-1]) - 1
    out["rise_from_low60"] = c[-1] / low60 - 1
    out["volume_spike"] = v[-1] / mean_v20
    # The same hard anti-chasing filters used by r09.
    if (out["ret5"] > 0.12 or out["ret20"] > 0.20 or out["rise_from_low60"] > 0.30
            or out["volume_spike"] > 5 or high[-1] == low[-1]
            or float(x["quote_rate"].iloc[-1]) >= 19.5 or amount20 < 50000000
            or bool(x["is_st"].iloc[-1])):
        return None
    values = [float(out[name]) for name in g.model["features"]]
    if not np.all(np.isfinite(values)):
        return None
    return values



def _load_extra_model(encoded):
    raw = zlib.decompress(base64.b64decode(encoded.encode("ascii")))
    return json.loads(raw.decode("utf-8"))


def _prepare_portable(model):
    model["fast_trees"] = [
        (np.asarray([n["f"] for n in tree], dtype=np.int16),
         np.asarray([n["t"] for n in tree]),
         np.asarray([n["m"] for n in tree], dtype=bool),
         np.asarray([n["l"] for n in tree], dtype=np.int16),
         np.asarray([n["r"] for n in tree], dtype=np.int16),
         np.asarray([n["leaf"] for n in tree], dtype=bool),
         np.asarray([n["v"] for n in tree])) for tree in model["trees"]
    ]
    return model


def _bear_model_for_today(today):
    key = today.strftime("%Y-%m-%d")
    selected = None
    for model in g.bear_bundle["models"]:
        if model["start"] <= key and key <= model["end"]:
            return model
        if model["start"] <= key:
            selected = model
    return selected


def _market_values(frames):
    series = []
    for symbol in frames:
        frame = frames[symbol]
        if frame is None or len(frame) < 61:
            continue
        series.append(frame.sort_index()["close"].astype(float).rename(symbol).iloc[-61:])
    if not series:
        return None, None
    close = pd.concat(series, axis=1).sort_index().tail(61)
    ret = close / close.shift(1) - 1.0
    mret = ret.mean(axis=1).fillna(0.0)
    nav = (1.0 + mret).cumprod()
    out = {}
    out["mret5"] = float(nav.iloc[-1] / nav.iloc[-6] - 1.0)
    out["mret20"] = float(nav.iloc[-1] / nav.iloc[-21] - 1.0)
    out["mret60"] = float(nav.iloc[-1] / nav.iloc[-61] - 1.0)
    out["mvol20"] = float(mret.iloc[-20:].std())
    out["breadth1"] = float((ret.iloc[-5:] > 0).mean(axis=1).mean())
    out["breadth20"] = float((close.iloc[-1] / close.iloc[-21] - 1.0 > 0).mean())
    out["dispersion"] = float(ret.iloc[-5:].std(axis=1).mean())
    out["downside_share"] = float((ret.iloc[-5:] < -0.03).mean(axis=1).mean())
    cross_var = float(ret.var(axis=1).iloc[-20:].mean())
    out["common_risk"] = min(1.0, max(0.0, float(mret.iloc[-20:].var()) / cross_var)) if cross_var > 0 else 0.0
    out["avg_dd20"] = float((close.iloc[-1] / close.iloc[-20:].max() - 1.0).mean())
    values = [float(out[name]) for name in g.bear_bundle["features"]]
    if not np.all(np.isfinite(values)):
        return None, close
    return values, close


def _downside_penalty(symbol, held_symbols, close):
    if close is None or symbol not in close.columns or not held_symbols:
        return 0.0
    ret = close.pct_change().tail(60)
    downside = ret.loc[ret.mean(axis=1) < 0]
    if len(downside) < 15:
        return 0.0
    x = downside[symbol].to_numpy(dtype=float)
    maximum = 0.0
    for held in held_symbols:
        if held not in downside.columns:
            continue
        y = downside[held].to_numpy(dtype=float)
        valid = np.isfinite(x) & np.isfinite(y)
        if int(valid.sum()) < 15:
            continue
        corr = float(np.corrcoef(x[valid], y[valid])[0, 1])
        if np.isfinite(corr):
            maximum = max(maximum, corr)
    return max(0.0, maximum)


def init(context):
    g.model = _load_model()
    g.model["fast_trees"] = [
        (np.asarray([n["f"] for n in tree], dtype=np.int16), np.asarray([n["t"] for n in tree]),
         np.asarray([n["m"] for n in tree], dtype=bool), np.asarray([n["l"] for n in tree], dtype=np.int16),
         np.asarray([n["r"] for n in tree], dtype=np.int16), np.asarray([n["leaf"] for n in tree], dtype=bool),
         np.asarray([n["v"] for n in tree])) for tree in g.model["trees"]
    ]
    g.stop_model = _prepare_portable(_load_extra_model(_EMBEDDED_STOP_MODEL_B64))
    g.bear_bundle = _load_extra_model(_EMBEDDED_BEAR_MODELS_B64)
    for item in g.bear_bundle["models"]:
        _prepare_portable(item)
    g.bear_probability = 0.0
    g.risk_fraction = 0.10
    g.pending = []
    g.position_state = {}
    g.order_intent = {}
    g.order_locks = {}
    g.order_seen_fill = {}
    g.observed_amount = {}
    g.submitted_action = {}
    g.previous_close = {}
    g.daily_buy_value = 0.0
    g.daily_sell_value = 0.0
    g.buy_done_date = None
    set_benchmark("000688.SH")
    set_slippage(PriceSlippage(COST_SCENARIOS[COST_SCENARIO]))
    set_commission(PerShare(type="stock", cost=0.0003, min_trade_cost=5.0))
    set_volume_limit(daily=0.25, minute=0.5)
    log.info("Strategy3 bear-downside V1 initialized; daily frequency; model valid through 2026-09-30; cost=%s" % COST_SCENARIO)


def before_trading(context):
    today = get_datetime().date()
    g.order_locks = {}; g.order_intent = {}; g.order_seen_fill = {}; g.previous_close = {}
    g.daily_buy_value = 0.0; g.daily_sell_value = 0.0
    symbols = g.model["universe"]
    fields = ["open", "high", "low", "close", "volume", "turnover", "turnover_rate", "quote_rate", "is_st"]
    feature_rows = []; frames = {}
    for begin in range(0, len(symbols), 300):
        batch = symbols[begin:begin + 300]
        data = history(batch, fields, 121, "1d", True, "pre", True, False)
        for symbol in batch:
            frame = data.get(symbol) if isinstance(data, dict) else None
            if frame is not None and len(frame):
                frames[symbol] = frame
                g.previous_close[symbol] = float(frame.sort_index()["close"].iloc[-1])
            values = _last_features(frame)
            if values is not None:
                feature_rows.append((symbol, values))
    scored = []
    if feature_rows:
        values = [item[1] for item in feature_rows]
        up = _batch_probabilities(g.model, values)
        stop = _batch_probabilities(g.stop_model, values)
        held = list(context.portfolio.positions.keys())
        market_values, close = _market_values(frames)
        for i in range(len(feature_rows)):
            probability = float(up[i]); stop_probability = float(stop[i])
            if probability < g.model["threshold"] or stop_probability > 0.50:
                continue
            symbol = feature_rows[i][0]
            rank_score = probability - 0.22 * stop_probability
            rank_score -= 0.10 * _downside_penalty(symbol, held, close)
            scored.append((symbol, probability, rank_score, stop_probability))
        model = _bear_model_for_today(today)
        if model is not None and market_values is not None:
            g.bear_probability = float(_tree_probability(model, market_values))
        else:
            g.bear_probability = 0.0
    scored.sort(key=lambda item: item[2], reverse=True)
    g.pending = [(item[0], item[1]) for item in scored[:g.model["top_per_day"]]]
    if g.bear_probability >= 0.70: g.risk_fraction = 0.055
    elif g.bear_probability >= 0.55: g.risk_fraction = 0.075
    elif g.bear_probability >= 0.40: g.risk_fraction = 0.09
    else: g.risk_fraction = 0.10
    g.buy_done_date = None
    log.info("STRATEGY3 candidates=%s bear_probability=%.6f new_position=%.3f" %
             (str(g.pending), g.bear_probability, g.risk_fraction))


def _submit(symbol, target_amount, action):
    if symbol in g.order_locks:
        return
    order_id = order_target(symbol, int(target_amount))
    if order_id is not None:
        g.order_locks[symbol] = order_id
        g.order_intent[order_id] = {"symbol": symbol, "action": action}
        g.submitted_action[symbol] = {"action": action, "date": get_datetime().date()}


def _live_trade_state(symbol, bar_dict):
    """Return (tradable, locked_up, locked_down, price).

    The explicit check is deliberately conservative. A candidate locked at the
    upper limit is retried in later minute bars and can only be submitted after
    it opens. A sell remains pending in strategy state while the lower limit is
    locked. Platform matching and volume limits still make the final decision.
    """
    try:
        bar = bar_dict[symbol]
    except Exception:
        return False, False, False, np.nan
    price = float(bar.close)
    volume = float(bar.volume)
    paused = bool(bar.is_paused)
    if paused or not np.isfinite(price) or price <= 0 or volume <= 0:
        return False, False, False, price
    upper = float(bar.high_limit)
    lower = float(bar.low_limit)
    locked_up = np.isfinite(upper) and price >= upper * 0.999
    locked_down = np.isfinite(lower) and price <= lower * 1.001
    return True, bool(locked_up), bool(locked_down), price


def _available_cash(context):
    return float(context.portfolio.stock_account.available_cash)


def _reconcile_position_state(context):
    """Use actual account holdings as the source of truth every minute."""
    today = get_datetime().date()
    positions = context.portfolio.positions
    active = set(positions.keys())
    for symbol in list(g.position_state.keys()):
        if symbol not in active:
            g.position_state.pop(symbol, None)
    for symbol in list(g.observed_amount.keys()):
        if symbol not in active:
            g.observed_amount.pop(symbol, None)
            action = g.submitted_action.get(symbol)
            if action is None or action.get("action") != "BUY" or action.get("date") != today:
                g.submitted_action.pop(symbol, None)
    for symbol in active:
        pos = positions[symbol]
        amount = float(pos.amount)
        previous = float(g.observed_amount.get(symbol, 0.0))
        if symbol not in g.position_state or previous <= 0:
            entry_date = today if int(pos.position_days) <= 0 else None
            g.position_state[symbol] = {
                "entry": float(pos.cost_basis), "half": False, "entry_date": entry_date
            }
            g.submitted_action.pop(symbol, None)
        elif amount < previous:
            action = g.submitted_action.get(symbol)
            if action is not None and action.get("action") == "TPHALF":
                g.position_state[symbol]["half"] = True
            g.submitted_action.pop(symbol, None)
        g.observed_amount[symbol] = amount


def handle_bar(context, bar_dict):
    now = get_datetime()
    _reconcile_position_state(context)
    positions = context.portfolio.positions
    # Execute yesterday-close candidates once after today's open.
    if g.buy_done_date != now.date():
        pending_buys = sum(1 for x in g.order_intent.values() if x.get("action") == "BUY")
        slots = max(0, g.model["max_positions"] - len(positions) - pending_buys)
        for symbol, probability in g.pending:
            if slots <= 0:
                break
            if symbol in positions or symbol in g.order_locks:
                continue
            tradable, locked_up, _, price = _live_trade_state(symbol, bar_dict)
            if not tradable or locked_up:
                # Do not mark the day done: a limit-up candidate may open later.
                continue
            # STAR orders require at least 200 shares. This also prevents a
            # batch of target-percent orders from silently oversubscribing cash.
            if _available_cash(context) < price * 200 * 1.005:
                continue
            order_id = order_target_percent(symbol, g.risk_fraction)
            if order_id is not None:
                g.order_locks[symbol] = order_id
                g.order_intent[order_id] = {"symbol": symbol, "action": "BUY", "probability": probability}
                g.submitted_action[symbol] = {"action": "BUY", "date": now.date()}
                slots -= 1
        # Keep checking unsubmitted limit-up candidates until the final bars.
        if now.hour > 14 or (now.hour == 14 and now.minute >= 55):
            g.buy_done_date = now.date()
    # Minute-level risk management.
    for symbol in list(positions.keys()):
        pos = positions[symbol]
        if symbol not in g.position_state:
            g.position_state[symbol] = {"entry": float(pos.cost_basis), "half": False, "entry_date": None}
        state = g.position_state[symbol]
        # A-share T+1: shares bought today are not sellable today.
        if state.get("entry_date") == now.date() or int(pos.position_days) <= 0:
            continue
        tradable, _, locked_down, _ = _live_trade_state(symbol, bar_dict)
        if not tradable or locked_down:
            continue
        price = float(pos.last_price)
        if price <= state["entry"] * 0.93:
            _submit(symbol, 0, "STOP")
        elif price >= state["entry"] * 1.34:
            _submit(symbol, 0, "TPALL")
        elif price >= state["entry"] * 1.24 and not state["half"]:
            target = max(0, int(pos.amount / 2))
            sell_amount = int(pos.amount) - target
            if target >= 200 and sell_amount >= 200:
                _submit(symbol, target, "TPHALF")
        elif int(pos.position_days) >= 30:
            _submit(symbol, 0, "TIME")


def on_order(context, odr):
    intent = g.order_intent.get(odr.order_id)
    if intent is None:
        return
    status = str(odr.status)
    symbol, action = intent["symbol"], intent["action"]
    # Account for incremental fills when the callback reports cumulative size.
    filled = float(odr.filled_amount)
    price = float(odr.avg_price)
    previous = g.order_seen_fill.get(odr.order_id, 0.0)
    delta = max(0.0, filled - previous)
    g.order_seen_fill[odr.order_id] = max(previous, filled)
    if delta > 0 and price > 0:
        if action == "BUY": g.daily_buy_value += delta * price
        else: g.daily_sell_value += delta * price
    if "PART" in status:
        # A partial buy already creates a T+1 position even if the remainder is
        # later cancelled. Keep the order lock until its terminal callback.
        if action == "BUY":
            pos = context.portfolio.positions.get(symbol)
            if pos is not None:
                g.position_state[symbol] = {"entry": float(pos.cost_basis), "half": False,
                                            "entry_date": get_datetime().date()}
        log.info("partial %s %s filled=%s" % (action, symbol, str(filled)))
        return
    if "FILLED" in status:
        if action == "BUY":
            pos = context.portfolio.positions.get(symbol)
            if pos is not None:
                g.position_state[symbol] = {"entry": float(pos.cost_basis), "half": False,
                                            "entry_date": get_datetime().date()}
        elif action == "TPHALF" and symbol in g.position_state:
            g.position_state[symbol]["half"] = True
        elif action in ("STOP", "TPALL", "TIME"):
            pos = context.portfolio.positions.get(symbol)
            if pos is None or float(pos.amount) <= 0:
                g.position_state.pop(symbol, None)
        g.order_locks.pop(symbol, None)
        g.order_intent.pop(odr.order_id, None)
        log.info("filled %s %s" % (action, symbol))
    elif "REJECTED" in status or "CANCELLED" in status:
        # Reconcile a partially-filled buy before releasing its lock.
        if action == "BUY":
            pos = context.portfolio.positions.get(symbol)
            if pos is not None and float(pos.amount) > 0:
                g.position_state[symbol] = {"entry": float(pos.cost_basis), "half": False,
                                            "entry_date": get_datetime().date()}
        g.order_locks.pop(symbol, None)
        g.order_intent.pop(odr.order_id, None)
        g.order_seen_fill.pop(odr.order_id, None)
        log.warn("order failed %s %s" % (action, symbol))


def after_trading(context):
    _reconcile_position_state(context)
    total = float(context.portfolio.stock_account.total_value)
    gross = g.daily_buy_value + g.daily_sell_value
    turnover = gross / total if total > 0 else np.nan
    log.info("EXECUTION_AUDIT buy=%.2f sell=%.2f gross=%.2f nav=%.2f turnover=%.4f open_intents=%d" %
             (g.daily_buy_value, g.daily_sell_value, gross, total, turnover, len(g.order_intent)))
